def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Identify the dominant background color.
    counts = [0] * 10
    for row in grid:
        for value in row:
            counts[value] += 1
    bg = max(range(10), key=lambda c: counts[c])
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            # A hollow rectangular frame has a complete colored perimeter.
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            if not all(grid[r0][x] == color and grid[r1][x] == color for x in range(c0, c1 + 1)):
                continue
            if not all(grid[y][c0] == color and grid[y][c1] == color for y in range(r0, r1 + 1)):
                continue
            if any(grid[y][x] != bg for y in range(r0 + 1, r1) for x in range(c0 + 1, c1)):
                continue
            fill = 2 if (r1 - r0 + 1) % 2 == 0 else 7
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    out[y][x] = fill
    return out


if __name__ == '__main__':
    pass
